use dioxus::prelude::*;
use api::{MoodEntry, MoodLevel};
use plotters::prelude::*;
use chrono::{DateTime, Utc};

#[component]
pub fn MoodLineChart(moods: Vec<MoodEntry>, height: Option<i32>) -> Element {
    let height = height.unwrap_or(400);
    let chart_id = use_signal(|| format!("mood-chart-{}", uuid::Uuid::new_v4()));

    // Draw chart after render
    use_effect(move || {
        let id = chart_id.read().clone();
        let moods = moods.clone();
        spawn(async move {
            draw_mood_chart(&id, &moods, height);
        });
    });

    rsx! {
        div { class: "mood-chart-container",
            canvas {
                id: "{chart_id.read()}",
                width: "800",
                height: "{height}",
            }
        }
    }
}

#[cfg(target_arch = "wasm32")]
fn draw_mood_chart(canvas_id: &str, moods: &[MoodEntry], height: i32) {
    use web_sys::HtmlCanvasElement;
    use wasm_bindgen::JsCast;

    let document = web_sys::window().unwrap().document().unwrap();
    let canvas = document
        .get_element_by_id(canvas_id)
        .unwrap()
        .dyn_into::<HtmlCanvasElement>()
        .unwrap();

    let backend = CanvasBackend::with_canvas_object(canvas).unwrap();
    let root = backend.into_drawing_area();
    root.fill(&WHITE).unwrap();

    // Prepare data points
    let data_points: Vec<(DateTime<Utc>, f64)> = moods
        .iter()
        .map(|m| {
            let value = mood_to_value(&m.mood);
            (m.timestamp, value)
        })
        .collect();

    if data_points.is_empty() {
        // Draw "No data" message
        root.draw_text(
            "No mood data available",
            &TextStyle::from(("sans-serif", 20).into_font()).color(&BLACK),
            (400, height / 2),
        )
        .unwrap();
        root.present().unwrap();
        return;
    }

    let min_time = data_points.iter().map(|(t, _)| *t).min().unwrap();
    let max_time = data_points.iter().map(|(t, _)| *t).max().unwrap();

    let mut chart = ChartBuilder::on(&root)
        .margin(10)
        .x_label_area_size(30)
        .y_label_area_size(40)
        .build_cartesian_2d(min_time..max_time, 1.0..5.0)
        .unwrap();

    chart
        .configure_mesh()
        .y_desc("Mood")
        .y_label_formatter(&|y| match *y as i32 {
            5 => "Very Happy".to_string(),
            4 => "Happy".to_string(),
            3 => "Neutral".to_string(),
            2 => "Sad".to_string(),
            1 => "Very Sad".to_string(),
            _ => "".to_string(),
        })
        .draw()
        .unwrap();

    // Draw line
    chart
        .draw_series(LineSeries::new(
            data_points.iter().map(|(t, v)| (*t, *v)),
            &BLUE,
        ))
        .unwrap();

    // Draw points with color based on mood
    chart
        .draw_series(data_points.iter().zip(moods.iter()).map(|((t, v), m)| {
            let color = mood_to_color(&m.mood);
            Circle::new((*t, *v), 4, color.filled())
        }))
        .unwrap();

    root.present().unwrap();
}

fn mood_to_value(mood: &MoodLevel) -> f64 {
    match mood {
        MoodLevel::VeryHappy => 5.0,
        MoodLevel::Happy => 4.0,
        MoodLevel::Neutral => 3.0,
        MoodLevel::Sad => 2.0,
        MoodLevel::VerySad => 1.0,
    }
}

fn mood_to_color(mood: &MoodLevel) -> RGBColor {
    match mood {
        MoodLevel::VeryHappy => RGBColor(34, 197, 94),  // green-500
        MoodLevel::Happy => RGBColor(132, 204, 22),     // lime-500
        MoodLevel::Neutral => RGBColor(234, 179, 8),    // yellow-500
        MoodLevel::Sad => RGBColor(249, 115, 22),       // orange-500
        MoodLevel::VerySad => RGBColor(239, 68, 68),    // red-500
    }
}

