-- Add role column to users table for Phase 1: Authentication
-- This allows differentiation between Individual users and Healthcare Providers

-- SQLite doesn't have "ADD COLUMN IF NOT EXISTS", so we need to check first
-- We'll use a safer approach: try to add the column, and if it fails, that's okay
-- because it already exists

-- Check if column exists by trying to select from it
-- If it doesn't exist, we'll recreate the table
CREATE TABLE IF NOT EXISTS users_new (
  id TEXT PRIMARY KEY NOT NULL,
  username TEXT UNIQUE NOT NULL,
  email TEXT UNIQUE NOT NULL,
  password_hash TEXT NOT NULL,
  display_name TEXT,
  role TEXT NOT NULL DEFAULT '"Individual"',
  created_at TEXT NOT NULL DEFAULT (datetime('now')),
  updated_at TEXT NOT NULL DEFAULT (datetime('now')),
  last_login_at TEXT
);

-- Copy data from old table, providing default role if column doesn't exist
INSERT OR IGNORE INTO users_new (id, username, email, password_hash, display_name, role, created_at, updated_at, last_login_at)
SELECT id, username, email, password_hash, display_name,
       COALESCE(role, '"Individual"') as role,
       created_at, updated_at, last_login_at
FROM users;

-- Drop old table and rename new one
DROP TABLE IF EXISTS users;
ALTER TABLE users_new RENAME TO users;

-- Recreate indexes
CREATE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE INDEX IF NOT EXISTS idx_users_email ON users(email);
CREATE INDEX IF NOT EXISTS idx_users_created_at ON users(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_users_role ON users(role);

-- Update schema version
UPDATE schema_metadata SET value='8' WHERE key='version';
INSERT OR IGNORE INTO schema_metadata (key, value) VALUES ('version', '8');

//! Data models for the Healthy Mind mental health app.

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// User role types for authentication
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum UserRole {
    Individual,  // Individual user tracking their own mental health
    Provider,    // Healthcare provider managing multiple patients
}

impl Default for UserRole {
    fn default() -> Self {
        UserRole::Individual
    }
}

/// Represents different mood levels
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum MoodLevel {
    VeryHappy,
    Happy,
    Neutral,
    Sad,
    VerySad,
}

impl MoodLevel {
    /// Returns emoji representation of the mood
    pub fn emoji(&self) -> &'static str {
        match self {
            MoodLevel::VeryHappy => "😄",
            MoodLevel::Happy => "🙂",
            MoodLevel::Neutral => "😐",
            MoodLevel::Sad => "😔",
            MoodLevel::VerySad => "😢",
        }
    }

    /// Returns color representation for UI
    pub fn color(&self) -> &'static str {
        match self {
            MoodLevel::VeryHappy => "#4CAF50",
            MoodLevel::Happy => "#8BC34A",
            MoodLevel::Neutral => "#FFC107",
            MoodLevel::Sad => "#FF9800",
            MoodLevel::VerySad => "#F44336",
        }
    }

    /// Returns label for the mood
    pub fn label(&self) -> &'static str {
        match self {
            MoodLevel::VeryHappy => "Very Happy",
            MoodLevel::Happy => "Happy",
            MoodLevel::Neutral => "Neutral",
            MoodLevel::Sad => "Sad",
            MoodLevel::VerySad => "Very Sad",
        }
    }

    /// Returns all mood levels in order
    pub fn all() -> Vec<MoodLevel> {
        vec![
            MoodLevel::VeryHappy,
            MoodLevel::Happy,
            MoodLevel::Neutral,
            MoodLevel::Sad,
            MoodLevel::VerySad,
        ]
    }
}

/// Mood entry with timestamp and optional notes
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct MoodEntry {
    pub id: Uuid,
    pub user_id: Uuid,
    pub mood: MoodLevel,
    pub notes: Option<String>,
    pub timestamp: DateTime<Utc>,
}

impl MoodEntry {
    pub fn new(mood: MoodLevel, notes: Option<String>, user_id: Uuid) -> Self {
        Self {
            id: Uuid::new_v4(),
            user_id,
            mood,
            notes,
            timestamp: Utc::now(),
        }
    }
}

/// User account for authentication
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct User {
    pub id: Uuid,
    pub username: String,
    pub email: String,
    #[serde(skip_serializing)]
    pub password_hash: String,
    pub display_name: Option<String>,
    pub role: UserRole,
    pub created_at: DateTime<Utc>,
    pub updated_at: DateTime<Utc>,
    pub last_login_at: Option<DateTime<Utc>>,
}

impl User {
    pub fn new(
        username: String,
        email: String,
        password_hash: String,
        display_name: Option<String>,
        role: UserRole,
    ) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4(),
            username,
            email,
            password_hash,
            display_name,
            role,
            created_at: now,
            updated_at: now,
            last_login_at: None,
        }
    }
}

/// Session token for authenticated users
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Session {
    pub id: Uuid,
    pub user_id: Uuid,
    pub created_at: DateTime<Utc>,
    pub expires_at: DateTime<Utc>,
    pub last_active_at: DateTime<Utc>,
}

impl Session {
    pub fn new(user_id: Uuid, duration_days: i64) -> Self {
        let now = Utc::now();
        Self {
            id: Uuid::new_v4(),
            user_id,
            created_at: now,
            expires_at: now + chrono::Duration::days(duration_days),
            last_active_at: now,
        }
    }

    pub fn is_expired(&self) -> bool {
        Utc::now() > self.expires_at
    }
}

// ===== Phase 6: Theme & Preferences =====

/// Theme preference
#[derive(Debug, Clone, Copy, Serialize, Deserialize, PartialEq)]
pub enum Theme {
    Light,
    Dark,
    Auto, // System preference
}

/// User preferences (Phase 6)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UserPreferences {
    pub user_id: Uuid,
    pub theme: Theme,
    pub language: String, // Language code: "en", "es", etc.
    pub timezone: String,
    pub updated_at: DateTime<Utc>,
}

impl UserPreferences {
    pub fn new(user_id: Uuid) -> Self {
        Self {
            user_id,
            theme: Theme::Light,
            language: "en".to_string(),
            timezone: "UTC".to_string(),
            updated_at: Utc::now(),
        }
    }
}

/// Notification settings (Phase 6)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct NotificationSettings {
    pub user_id: Uuid,
    pub enabled: bool,
    pub daily_reminder: bool,
    pub daily_reminder_time: String, // "09:00"
    pub achievements: bool,
    pub insights: bool,
    pub updated_at: DateTime<Utc>,
}

impl NotificationSettings {
    pub fn new(user_id: Uuid) -> Self {
        Self {
            user_id,
            enabled: true,
            daily_reminder: true,
            daily_reminder_time: "09:00".to_string(),
            achievements: true,
            insights: true,
            updated_at: Utc::now(),
        }
    }
}

// ===== Phase 7: Sync & Encryption =====

/// Sync configuration (Phase 7)
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SyncConfiguration {
    pub user_id: Uuid,
    pub enabled: bool,
    pub sync_interval_minutes: u32,
    pub end_to_end_encryption: bool,
    pub last_sync_at: Option<DateTime<Utc>>,
    pub sync_token: Option<String>,
}

impl SyncConfiguration {
    pub fn new(user_id: Uuid) -> Self {
        Self {
            user_id,
            enabled: false,
            sync_interval_minutes: 30,
            end_to_end_encryption: true,
            last_sync_at: None,
            sync_token: None,
        }
    }
}

